                    <h2 id="endpoints-GETapi-v1-directory-top-rated">Top N restaurants by average rating, for the homepage&#039;s &quot;best rated&quot; spotlight.</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Ratings are computed, not a stored column, so this ranks in PHP rather than
relying on the paginated <code>index()</code> query's DB-level ordering.</p>

<span id="example-requests-GETapi-v1-directory-top-rated">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/directory/top-rated" \
    --header "Authorization: Bearer {YOUR_SANCTUM_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/directory/top-rated"
);

const headers = {
    "Authorization": "Bearer {YOUR_SANCTUM_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
    method: "GET",
    headers,
}).then(response =&gt; response.json());</code></pre></div>

